import Link from "next/link";
import { GiEvilBook } from "react-icons/gi";
import { HiOutlineBookOpen } from "react-icons/hi2";
import { RiQuillPenLine } from "react-icons/ri";

import type { Manga } from "@/lib/catalog";
import { legacyMangaCover } from "@/lib/catalog";
import { MediaImage } from "@/components/MediaImage/page";
import styles from "./mangacard.module.css";

function MangaCard({ pageTitle, mangas }: { pageTitle: string; mangas: Manga[] }) {
  return (
    <section>
      <h2 className={styles.sectionTitleWrapper}>
        <HiOutlineBookOpen className={styles.sectionIcon} size={25} />
        <span className={styles.sectionTitle}>{pageTitle}</span>
      </h2>
      {mangas.length === 0 ? (
        <p>Nenhuma obra com capítulos publicados até o momento.</p>
      ) : (
        <div className={styles.mangasGrid}>
          {mangas.map((manga) => {
            return (
              <Link key={manga.id} href={`/title/${manga.id}`} className={styles.cardLink}>
                <article className={styles.mangaCard}>
                  <figure>
                    <div className={styles.mangaWraper}>
                      <MediaImage className={styles.mangaCover} source={manga.mangaCover || legacyMangaCover(manga.title) || manga.previewImage} alt={`Capa de ${manga.title}`} />
                    </div>
                    <figcaption className={styles.mangaInfo}>
                      <div className={styles.mangaInfoLine}><GiEvilBook size={16} /><span>{manga.title}</span></div>
                      <hr className={styles.hrFaded} />
                      <div className={styles.mangaInfoLine}><RiQuillPenLine size={16} /><span>{manga.mangaka}</span></div>
                    </figcaption>
                  </figure>
                </article>
              </Link>
            );
          })}
        </div>
      )}
    </section>
  );
}

export { MangaCard };
