import { BiHash, BiLike } from "react-icons/bi";
import { FaArrowTrendUp } from "react-icons/fa6";
import { HiOutlineBookOpen } from "react-icons/hi2";
import { IoIosGlobe } from "react-icons/io";
import { MdOutlinePeopleOutline } from "react-icons/md";

import type { Group } from "@/lib/catalog";
import { legacyGroupImage } from "@/lib/catalog";
import { MediaImage } from "@/components/MediaImage/page";
import styles from "./scaninfo.module.css";

const socialLabels: Record<string, string> = {
  site: "Site", discord: "Discord", telegram: "Telegram", x: "Twitter/X",
  instagram: "Instagram", facebook: "Facebook", bluesky: "Bluesky",
  orkut: "Orkkut", email: "Email",
};

function ScanInfo({ scan }: { scan: Group }) {
  const links = Object.entries(scan.socialMedias ?? {}).filter(([, value]) => value);

  return (
    <section className={styles.scanInfoContainer}>
      <div>
        <div className={styles.scanWrapper}>
          <MediaImage className={styles.scanPicture} source={scan.groupImage || legacyGroupImage(scan.name) || scan.previewImage} alt={`Imagem da ${scan.name}`} />
        </div>
        <div className={styles.btnWrapper}>
          <button className={styles.btnFollow} disabled><span>Seguir Scan</span></button>
        </div>
      </div>
      <div className={styles.scanInfo}>
        <h1 className={styles.scanNameWrapper}><span className={styles.scanName}>{scan.name}</span></h1>
        <p className={styles.sinopse}>{scan.description}</p>
        <div className={styles.statsContainer}>
          <h3 className={styles.statsTitle}>Estatísticas</h3>
          <div className={styles.stats}>
            <span className={styles.stat}><MdOutlinePeopleOutline size={18} /><span>{scan.stats.followers} Seguidores</span></span>
            <span className={styles.stat}><HiOutlineBookOpen size={16} /><span>{scan.stats.mangas} Mangás</span></span>
            <span className={styles.stat}><BiHash size={16} /><span>{scan.stats.chapters} Caps</span></span>
            <span className={styles.stat}><FaArrowTrendUp size={16} /><span>{scan.stats.views} Views</span></span>
            <span className={styles.stat}><BiLike size={16} /><span>{scan.stats.likes} Likes</span></span>
          </div>
        </div>
        {links.length > 0 && (
          <div className={styles.mediasContainer}>
            <h3 className={styles.mediasTitle}>Links</h3>
            <div className={styles.medias}>
              {links.map(([key, value]) => (
                <a className={styles.media} href={key === "email" ? `mailto:${value}` : String(value)} key={key} target={key === "email" ? undefined : "_blank"} rel="noreferrer">
                  <IoIosGlobe size={16} /><span>{socialLabels[key] ?? key}</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

export { ScanInfo };
